def get_level(level_number):
    try:
        level_number = int(level_number)
    except (TypeError, ValueError):
        return None
    return LEVEL_MAP.get(level_number)


def stars_for_percentage(percentage):
    if percentage >= 90:
        return 3
    if percentage >= 70:
        return 2
    if percentage >= 50:
        return 1
    return 0
